sys_script_include.script:
var appointedPosition = Class.create();
appointedPosition.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    appointedPosition: function() {
        var user = this.getParameter('sysparm_user');
        var created = this.getParameter('sysparm_created');

        //Queries Appointed Positions Table for defined user	
        var grUser = new GlideRecord('x_g_dh5_appointed_appointed_positions');
        grUser.addQuery('user', user);
        grUser.query();

        //Processes each returned record
        while (grUser.next()) {
            var gdt1 = new GlideDateTime(created);
            var gdt2 = new GlideDateTime(grUser.start_date);
            var gdt3 = new GlideDateTime(grUser.end_date);

            if (gdt2.before(gdt1) && gdt3.after(gdt1)) {
                return true;
            } else if (gdt2.before(gdt1) && gdt3 == "") {
                return true;
            } else {
                return false;
            }

        }

        if (gs.nil(grUser)) {
            return false;
        }

    },

    type: 'appointedPosition'

});
